//! Test fixtures made with openssl (see the commands per item). Generated
//! once and pasted as hex; regenerate together, they belong to each other.

/// `openssl ecparam -name prime256v1 -genkey` + `openssl req -x509
/// -subj "/CN=Home Test CA/O=Home" -addext basicConstraints=critical,CA:TRUE
/// -days 3650` (DER).
pub const CA: &str = "";

/// A leaf signed by [`CA`]: `-subj "/CN=gw.example.com/O=Home" -addext
/// "subjectAltName=DNS:gw.example.com,DNS:alt.example.com,IP:10.0.0.1"
/// -days 365`, valid from 2026-10-25 20:44:12 UTC.
pub const LEAF: &str = "";
pub const LEAF_NOT_BEFORE: i64 = 1_792_961_052;
pub const LEAF_NOT_AFTER: i64 = 1_824_497_052;

/// The leaf's private key (the P-256 scalar) and public point.
pub const LEAF_KEY: &str = "0a74e7a8142ff6856a1060e4e726c5b78008b92f3c98a65267f4377a7382519c";
pub const LEAF_POINT: &str = "04247eaabffbb976a24614a6589457b6a59adea8fc438168721832831e3abd11fafb4dbc2f09c6879801965e20e1fa859a12b9f372ea1ca55025ada16ccfe4027b";

/// `openssl crl2pkcs7 -nocrl -certfile ca.pem -certfile leaf.pem`: an EST
/// style certs-only PKCS#7 with both, CA first.
pub const P7_CERTS_ONLY: &str = "";

pub fn unhex(text: &str) -> std::vec::Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}
